(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1191],{56271:function(n,e,a){Promise.resolve().then(a.bind(a,19538))},19538:function(n,e,a){"use strict";a.r(e),a.d(e,{default:function(){return t}});var o=a(57437);function t(){return(0,o.jsx)("div",{dangerouslySetInnerHTML:{__html:'<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Pr\xe9-Consulta – CTO</title>\n  <style>\n    :root {\n      --azul: #1a4fa0;\n      --azul-claro: #e8f0fc;\n      --vermelho: #cc3300;\n      --cinza: #555;\n      --borda: #dce3ef;\n      --radius: 10px;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n      background: #f4f6fb;\n      color: #222;\n      min-height: 100vh;\n    }\n    header {\n      background: var(--azul);\n      color: white;\n      padding: 16px 20px 14px;\n    }\n    header h1 { font-size: 17px; font-weight: 700; }\n    header p  { font-size: 12px; opacity: .85; margin-top: 2px; }\n\n    .progresso {\n      background: white;\n      border-bottom: 1px solid var(--borda);\n      padding: 12px 20px;\n      position: sticky;\n      top: 0;\n      z-index: 10;\n    }\n    .prog-dots {\n      display: flex;\n      gap: 8px;\n      align-items: center;\n      margin-bottom: 4px;\n    }\n    .dot {\n      width: 10px; height: 10px;\n      border-radius: 50%;\n      background: #cdd5e0;\n      transition: background .3s;\n    }\n    .dot.ativo   { background: var(--azul); }\n    .dot.feito   { background: #27ae60; }\n    .prog-texto  { font-size: 12px; color: var(--cinza); }\n    .prog-bar    { height: 4px; background: #e0e4ee; border-radius: 2px; margin-top: 8px; }\n    .prog-fill   { height: 100%; background: var(--azul); border-radius: 2px; transition: width .4s; }\n\n    main { max-width: 520px; margin: 0 auto; padding: 0 16px 100px; }\n\n    .secao {\n      display: none;\n      padding-top: 20px;\n    }\n    .secao.ativa { display: block; }\n\n    .secao-titulo {\n      font-size: 15px;\n      font-weight: 700;\n      color: var(--azul);\n      margin-bottom: 16px;\n      padding-bottom: 8px;\n      border-bottom: 2px solid var(--azul-claro);\n    }\n\n    .campo { margin-bottom: 16px; }\n    label {\n      display: block;\n      font-size: 13px;\n      font-weight: 600;\n      color: var(--cinza);\n      margin-bottom: 5px;\n    }\n    label .opt { font-weight: 400; color: #999; }\n\n    input[type=text],\n    input[type=date],\n    input[type=number],\n    select,\n    textarea {\n      width: 100%;\n      padding: 11px 13px;\n      border: 1.5px solid var(--borda);\n      border-radius: var(--radius);\n      font-size: 15px;\n      color: #222;\n      background: white;\n      transition: border-color .2s;\n      -webkit-appearance: none;\n    }\n    input:focus, select:focus, textarea:focus {\n      outline: none;\n      border-color: var(--azul);\n    }\n    textarea { min-height: 80px; resize: vertical; }\n\n    input[readonly], select[disabled] {\n      background: #f0f3f9;\n      color: #666;\n    }\n\n    .slider-wrap { position: relative; padding-bottom: 20px; }\n    input[type=range] {\n      width: 100%;\n      -webkit-appearance: none;\n      height: 8px;\n      border-radius: 4px;\n      background: linear-gradient(to right, var(--azul) 0%, var(--azul) 0%, #dce3ef 0%);\n      border: none;\n      padding: 0;\n    }\n    input[type=range]::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      width: 24px; height: 24px;\n      border-radius: 50%;\n      background: var(--azul);\n      cursor: pointer;\n      border: 3px solid white;\n      box-shadow: 0 0 4px rgba(0,0,0,.25);\n    }\n    .slider-labels {\n      display: flex;\n      justify-content: space-between;\n      font-size: 11px;\n      color: #999;\n      margin-top: 4px;\n    }\n    .eva-val {\n      text-align: center;\n      font-size: 28px;\n      font-weight: 700;\n      color: var(--azul);\n      line-height: 1;\n    }\n    .eva-desc {\n      text-align: center;\n      font-size: 12px;\n      color: var(--cinza);\n      margin-top: 2px;\n    }\n\n    .radio-group, .check-group {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n    .radio-group label, .check-group label {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      background: white;\n      border: 1.5px solid var(--borda);\n      border-radius: 20px;\n      padding: 7px 14px;\n      font-size: 14px;\n      font-weight: 500;\n      color: #333;\n      cursor: pointer;\n      transition: border-color .15s, background .15s;\n      margin-bottom: 0;\n    }\n    .radio-group input, .check-group input { display: none; }\n    .radio-group label:has(input:checked),\n    .check-group label:has(input:checked) {\n      border-color: var(--azul);\n      background: var(--azul-claro);\n      color: var(--azul);\n    }\n\n    .upload-area {\n      border: 2px dashed var(--borda);\n      border-radius: var(--radius);\n      background: white;\n      padding: 24px;\n      text-align: center;\n      cursor: pointer;\n      transition: border-color .2s;\n    }\n    .upload-area:hover { border-color: var(--azul); }\n    .upload-area p { font-size: 14px; color: #999; margin-top: 6px; }\n    .upload-icon { font-size: 32px; }\n    #upload-input { display: none; }\n\n    .miniaturas {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      margin-top: 10px;\n    }\n    .miniatura {\n      background: #e8f0fc;\n      border-radius: 8px;\n      padding: 6px 10px;\n      font-size: 12px;\n      color: var(--azul);\n      display: flex;\n      align-items: center;\n      gap: 5px;\n    }\n    .spinner {\n      display: none;\n      width: 18px; height: 18px;\n      border: 2px solid var(--borda);\n      border-top-color: var(--azul);\n      border-radius: 50%;\n      animation: spin .7s linear infinite;\n    }\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .botoes {\n      position: fixed;\n      bottom: 0; left: 0; right: 0;\n      background: white;\n      border-top: 1px solid var(--borda);\n      padding: 12px 20px;\n      display: flex;\n      gap: 10px;\n      max-width: 520px;\n      margin: 0 auto;\n    }\n    @media (min-width: 552px) {\n      .botoes { left: 50%; right: auto; transform: translateX(-50%); width: 520px; }\n    }\n\n    button {\n      flex: 1;\n      padding: 14px;\n      border: none;\n      border-radius: var(--radius);\n      font-size: 15px;\n      font-weight: 700;\n      cursor: pointer;\n      transition: opacity .2s;\n    }\n    button:disabled { opacity: .5; cursor: not-allowed; }\n    .btn-prox { background: var(--azul); color: white; }\n    .btn-ant  { background: #eef1f7; color: #444; flex: 0 0 80px; }\n    .btn-enviar { background: #27ae60; color: white; }\n\n    .erro-campo {\n      font-size: 12px;\n      color: var(--vermelho);\n      margin-top: 4px;\n      display: none;\n    }\n    .campo.invalido input,\n    .campo.invalido select,\n    .campo.invalido textarea {\n      border-color: var(--vermelho);\n    }\n    .campo.invalido .erro-campo { display: block; }\n\n    .info-box {\n      background: #fff8e1;\n      border: 1px solid #ffe082;\n      border-radius: var(--radius);\n      padding: 12px 14px;\n      font-size: 13px;\n      color: #7a5c00;\n      margin-bottom: 16px;\n    }\n\n    #tela-expirado {\n      display: none;\n      text-align: center;\n      padding: 60px 24px;\n    }\n    #tela-expirado .icon { font-size: 52px; margin-bottom: 16px; }\n    #tela-expirado h2 { font-size: 18px; color: #333; margin-bottom: 10px; }\n    #tela-expirado p  { font-size: 14px; color: #666; margin-bottom: 24px; }\n    #tela-expirado a {\n      display: inline-block;\n      background: #25d366;\n      color: white;\n      text-decoration: none;\n      padding: 14px 28px;\n      border-radius: 30px;\n      font-weight: 700;\n      font-size: 15px;\n    }\n  </style>\n</head>\n<body>\n\n<div id="tela-expirado">\n  <div class="icon">⏰</div>\n  <h2>Link n\xe3o est\xe1 mais dispon\xedvel</h2>\n  <p>Este link n\xe3o est\xe1 mais dispon\xedvel. Sem problema — entre em contato pelo WhatsApp e reenviamos em instantes.</p>\n  <a href="https://wa.me/5581999179609">Falar com a cl\xednica →</a>\n</div>\n\n<div id="app" style="display:none">\n\n  <header>\n    <h1>CTO – Formul\xe1rio Pr\xe9-Consulta</h1>\n    <p>Dr. Valth Menezes Guimar\xe3es \xb7 CRM-PB 6326</p>\n  </header>\n\n  <div class="progresso">\n    <div class="prog-dots">\n      <div class="dot" id="d1"></div>\n      <div class="dot" id="d2"></div>\n      <div class="dot" id="d3"></div>\n      <div class="dot" id="d4"></div>\n      <div class="dot" id="d5"></div>\n      <span id="prog-label" class="prog-texto"></span>\n    </div>\n    <div class="prog-bar"><div class="prog-fill" id="prog-fill"></div></div>\n  </div>\n\n  <main>\n\n    <!-- Se\xe7\xe3o 1: Queixa Principal -->\n    <div class="secao ativa" id="sec1">\n      <div class="secao-titulo">Queixa Principal</div>\n\n      <div class="campo" id="c-regiao">\n        <label>Regi\xe3o do corpo afetada</label>\n        <select id="regiao_corpo">\n          <option value="">Selecione…</option>\n          <option value="joelho_dir">Joelho direito</option>\n          <option value="joelho_esq">Joelho esquerdo</option>\n          <option value="quadril">Quadril</option>\n          <option value="ombro">Ombro</option>\n          <option value="tornozelo">Tornozelo</option>\n          <option value="coluna">Coluna</option>\n          <option value="mao_punho">M\xe3o / Punho</option>\n          <option value="outro">Outro</option>\n        </select>\n        <div class="erro-campo">Por favor, selecione a regi\xe3o.</div>\n      </div>\n\n      <div class="campo" id="c-desc">\n        <label>Descreva com suas palavras o que est\xe1 sentindo</label>\n        <textarea id="descricao" placeholder="Ex: Dor ao subir escadas, incha\xe7o no joelho…" rows="3"></textarea>\n        <div class="erro-campo">Por favor, descreva o que est\xe1 sentindo.</div>\n      </div>\n\n      <div class="campo">\n        <label>H\xe1 quanto tempo tem esses sintomas?</label>\n        <select id="tempo_sintomas">\n          <option value="">Selecione…</option>\n          <option value="menos_1sem">Menos de 1 semana</option>\n          <option value="1_4sem">1 a 4 semanas</option>\n          <option value="1_6meses">1 a 6 meses</option>\n          <option value="mais_6meses">Mais de 6 meses</option>\n          <option value="mais_1ano">Mais de 1 ano</option>\n        </select>\n      </div>\n\n      <div class="campo">\n        <label>Como come\xe7ou?</label>\n        <div class="radio-group" id="mecanismo">\n          <label><input type="radio" name="mecanismo" value="gradual" /> Gradual</label>\n          <label><input type="radio" name="mecanismo" value="trauma" /> Ap\xf3s trauma / queda</label>\n          <label><input type="radio" name="mecanismo" value="esforco" /> Ap\xf3s esfor\xe7o</label>\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>Intensidade da dor agora</label>\n        <div class="slider-wrap">\n          <div class="eva-val" id="eva-val">5</div>\n          <div class="eva-desc" id="eva-desc">Dor moderada</div>\n          <input type="range" id="eva" min="0" max="10" value="5" />\n          <div class="slider-labels"><span>0 – Sem dor</span><span>10 – Dor m\xe1xima</span></div>\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>O que piora a dor? <span class="opt">(opcional)</span></label>\n        <input type="text" id="piora" placeholder="Ex: escadas, agachar, caminhar…" />\n      </div>\n\n      <div class="campo">\n        <label>O que alivia? <span class="opt">(opcional)</span></label>\n        <input type="text" id="melhora" placeholder="Ex: repouso, gelo, compressa…" />\n      </div>\n\n      <div class="campo">\n        <label>Fez algum tratamento antes? <span class="opt">(opcional)</span></label>\n        <input type="text" id="tratamento_anterior" placeholder="Ex: fisioterapia, medica\xe7\xe3o, cirurgia, nenhum…" />\n      </div>\n\n      <div class="campo">\n        <label>Usa algum analg\xe9sico? <span class="opt">(opcional)</span></label>\n        <input type="text" id="uso_analgesicos" placeholder="Ex: Ibuprofeno 400mg quando necess\xe1rio…" />\n      </div>\n    </div>\n\n    <!-- Se\xe7\xe3o 2: Identifica\xe7\xe3o -->\n    <div class="secao" id="sec2">\n      <div class="secao-titulo">Identifica\xe7\xe3o</div>\n\n      <div class="info-box">\n        Os campos abaixo j\xe1 foram preenchidos com as informa\xe7\xf5es do agendamento. Verifique se est\xe3o corretos.\n      </div>\n\n      <div class="campo">\n        <label>Nome completo</label>\n        <input type="text" id="nome" readonly />\n      </div>\n\n      <div class="campo">\n        <label>Telefone</label>\n        <input type="text" id="telefone" readonly />\n      </div>\n\n      <div class="campo" id="c-nasc">\n        <label>Data de nascimento</label>\n        <input type="date" id="nascimento" />\n        <div class="erro-campo">Informe sua data de nascimento.</div>\n      </div>\n\n      <div class="campo">\n        <label>CPF <span class="opt">(opcional)</span></label>\n        <input type="text" id="cpf" placeholder="000.000.000-00" maxlength="14" />\n      </div>\n\n      <div class="campo" id="c-cidade">\n        <label>Cidade</label>\n        <input type="text" id="cidade" placeholder="Ex: Campina Grande" />\n        <div class="erro-campo">Informe sua cidade.</div>\n      </div>\n\n      <div class="campo">\n        <label>Bairro <span class="opt">(opcional)</span></label>\n        <input type="text" id="bairro" placeholder="Ex: Catol\xe9" />\n      </div>\n\n      <div class="campo" id="c-profissao">\n        <label>Profiss\xe3o</label>\n        <input type="text" id="profissao" placeholder="Ex: Pedreiro, professora, motorista…" />\n        <div class="erro-campo">Informe sua profiss\xe3o.</div>\n      </div>\n\n      <div class="campo">\n        <label>Estado civil</label>\n        <select id="estado_civil">\n          <option value="">Selecione…</option>\n          <option value="solteiro">Solteiro(a)</option>\n          <option value="casado">Casado(a)</option>\n          <option value="uniao_estavel">Uni\xe3o est\xe1vel</option>\n          <option value="divorciado">Divorciado(a)</option>\n          <option value="viuvo">Vi\xfavo(a)</option>\n        </select>\n      </div>\n\n      <div class="campo">\n        <label>N\xfamero de filhos</label>\n        <input type="number" id="filhos" min="0" max="20" value="0" />\n      </div>\n    </div>\n\n    <!-- Se\xe7\xe3o 3: Sa\xfade Geral -->\n    <div class="secao" id="sec3">\n      <div class="secao-titulo">Sa\xfade Geral</div>\n\n      <div class="campo">\n        <label>Doen\xe7as cr\xf4nicas <span class="opt">(marque todas que se aplicam)</span></label>\n        <div class="check-group">\n          <label><input type="checkbox" name="doencas" value="has" /> HAS (press\xe3o alta)</label>\n          <label><input type="checkbox" name="doencas" value="dm" /> Diabetes</label>\n          <label><input type="checkbox" name="doencas" value="osteoporose" /> Osteoporose</label>\n          <label><input type="checkbox" name="doencas" value="artrite" /> Artrite</label>\n          <label><input type="checkbox" name="doencas" value="artrose" /> Artrose</label>\n          <label><input type="checkbox" name="doencas" value="obesidade" /> Obesidade</label>\n          <label><input type="checkbox" name="doencas" value="outra" /> Outra</label>\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>Medica\xe7\xf5es em uso cont\xednuo <span class="opt">(opcional)</span></label>\n        <input type="text" id="medicacoes" placeholder="Ex: Losartana 50mg, AAS 100mg" />\n      </div>\n\n      <div class="campo">\n        <label>Alergias a medicamentos <span class="opt">(especialmente dipirona / AINES)</span></label>\n        <input type="text" id="alergias" placeholder="Ex: Dipirona — ou \'nenhuma conhecida\'" />\n      </div>\n\n      <div class="campo">\n        <label>Cirurgias anteriores <span class="opt">(opcional)</span></label>\n        <input type="text" id="cirurgias_anteriores" placeholder="Ex: Apendicectomia 2010, joelho 2018" />\n      </div>\n\n      <div class="campo">\n        <label>Tabagismo</label>\n        <div class="radio-group" id="tabagismo">\n          <label><input type="radio" name="tabagismo" value="nunca" /> Nunca fumei</label>\n          <label><input type="radio" name="tabagismo" value="ex" /> Ex-fumante</label>\n          <label><input type="radio" name="tabagismo" value="atual" /> Fumante atual</label>\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>Consumo de \xe1lcool</label>\n        <div class="radio-group" id="alcool">\n          <label><input type="radio" name="alcool" value="nao" /> N\xe3o bebo</label>\n          <label><input type="radio" name="alcool" value="ocasional" /> Ocasional</label>\n          <label><input type="radio" name="alcool" value="frequente" /> Frequente</label>\n        </div>\n      </div>\n    </div>\n\n    <!-- Se\xe7\xe3o 4: Exames -->\n    <div class="secao" id="sec4">\n      <div class="secao-titulo">Exames <span style="font-weight:400;font-size:13px;color:#999">(opcional)</span></div>\n\n      <p style="font-size:13px;color:#666;margin-bottom:16px;">\n        Se tiver exames (raio-X, resson\xe2ncia, laudos), envie aqui. M\xe1ximo 5 arquivos de at\xe9 10MB cada.\n      </p>\n\n      <div class="upload-area" onclick="document.getElementById(\'upload-input\').click()">\n        <div class="upload-icon">\uD83D\uDCCE</div>\n        <p>Toque para selecionar imagens ou PDF</p>\n        <p style="font-size:11px;margin-top:2px;">JPG \xb7 PNG \xb7 PDF</p>\n        <div class="spinner" id="spinner-upload"></div>\n      </div>\n      <input type="file" id="upload-input" accept=".jpg,.jpeg,.png,.pdf" multiple />\n\n      <div class="miniaturas" id="miniaturas"></div>\n    </div>\n\n    <!-- Se\xe7\xe3o 5: Plano / Pagamento -->\n    <div class="secao" id="sec5">\n      <div class="secao-titulo">Forma de Pagamento</div>\n\n      <div class="campo">\n        <label>Como voc\xea vai pagar a consulta?</label>\n        <div class="radio-group" id="forma_pagamento">\n          <label><input type="radio" name="pagamento" value="particular" /> Particular</label>\n          <label><input type="radio" name="pagamento" value="convenio" /> Conv\xeanio / plano</label>\n        </div>\n      </div>\n\n      <div class="campo" id="campo-plano" style="display:none">\n        <label>Qual plano de sa\xfade?</label>\n        <input type="text" id="plano_saude" placeholder="Ex: Unimed, Bradesco Sa\xfade…" />\n      </div>\n\n      <div class="info-box" style="margin-top: 24px;">\n        ✅ Revise suas respostas antes de enviar. Ap\xf3s o envio, o Dr. Valth receber\xe1 um resumo antes da sua consulta.\n      </div>\n    </div>\n\n  </main>\n\n  <div class="botoes" id="botoes">\n    <button class="btn-ant" id="btn-ant" onclick="anterior()" style="display:none">← Voltar</button>\n    <button class="btn-prox" id="btn-prox" onclick="proximo()">Pr\xf3ximo →</button>\n  </div>\n\n</div>\n\n<script>\nconst params = new URLSearchParams(location.search);\nconst NOME        = params.get(\'nome\')   || \'\';\nconst TEL         = params.get(\'tel\')    || \'\';\nconst DATA        = params.get(\'data\')   || \'\';\nconst MOTIVO      = params.get(\'motivo\') || \'\';\nconst AID         = params.get(\'aid\')    || \'\';\nconst EXP         = params.get(\'exp\')    || \'\';\nconst TOKEN       = params.get(\'token\')  || \'\';\n\nconst TOTAL_SECOES = 5;\nconst TEMPO_EST = [\'~5 min restantes\',\'~4 min restantes\',\'~3 min restantes\',\'~2 min restantes\',\'\xdaltima etapa\'];\nlet secaoAtual = 1;\nconst examesUrls = [];\n\nfunction init() {\n  if (!TOKEN || !EXP || !AID) {\n    mostrarExpirado();\n    return;\n  }\n  if (Date.now() > parseInt(EXP)) {\n    mostrarExpirado();\n    return;\n  }\n\n  document.getElementById(\'app\').style.display = \'block\';\n  document.getElementById(\'nome\').value      = NOME;\n  document.getElementById(\'telefone\').value  = TEL;\n\n  const sel = document.getElementById(\'regiao_corpo\');\n  for (const opt of sel.options) {\n    if (MOTIVO.toLowerCase().includes(opt.value.replace(\'_\',\' \'))) {\n      opt.selected = true;\n      break;\n    }\n  }\n\n  atualizarProgresso();\n  initEva();\n  initUpload();\n  initPagamento();\n  initCPF();\n}\n\nfunction mostrarExpirado() {\n  document.getElementById(\'tela-expirado\').style.display = \'block\';\n}\n\nconst EVA_DESC = [\'Sem dor\',\'Dor m\xednima\',\'Dor leve\',\'Dor leve\',\'Dor moderada\',\'Dor moderada\',\n                  \'Dor intensa\',\'Dor intensa\',\'Dor muito intensa\',\'Dor severa\',\'Dor m\xe1xima\'];\nfunction initEva() {\n  const slider = document.getElementById(\'eva\');\n  function atualizar() {\n    const v = parseInt(slider.value);\n    document.getElementById(\'eva-val\').textContent  = v;\n    document.getElementById(\'eva-desc\').textContent = EVA_DESC[v];\n    const pct = (v / 10) * 100;\n    slider.style.background =\n      \'linear-gradient(to right, var(--azul) \' + pct + \'%, #dce3ef \' + pct + \'%)\';\n  }\n  slider.addEventListener(\'input\', atualizar);\n  atualizar();\n}\n\nfunction initUpload() {\n  const inp = document.getElementById(\'upload-input\');\n  inp.addEventListener(\'change\', async () => {\n    const files = Array.from(inp.files);\n    if (files.length + examesUrls.length > 5) {\n      alert(\'M\xe1ximo de 5 arquivos.\');\n      inp.value = \'\';\n      return;\n    }\n    for (const f of files) {\n      await uploadArquivo(f);\n    }\n    inp.value = \'\';\n  });\n}\n\nasync function uploadArquivo(arquivo) {\n  const spinner = document.getElementById(\'spinner-upload\');\n  spinner.style.display = \'block\';\n  try {\n    const form = new FormData();\n    form.append(\'arquivo\', arquivo);\n    const res = await fetch(\n      \'/pre-consulta/upload-exame?token=\' + TOKEN + \'&exp=\' + EXP + \'&agendamento_id=\' + AID,\n      { method: \'POST\', body: form }\n    );\n    if (!res.ok) {\n      const { erro } = await res.json();\n      if (erro === \'token_expirado\') { mostrarExpirado(); return; }\n      alert(\'Erro ao enviar \' + arquivo.name);\n      return;\n    }\n    const { url, nome } = await res.json();\n    examesUrls.push(url);\n    adicionarMiniatura(nome);\n  } catch {\n    alert(\'Falha de rede ao enviar \' + arquivo.name);\n  } finally {\n    spinner.style.display = \'none\';\n  }\n}\n\nfunction adicionarMiniatura(nome) {\n  const div = document.createElement(\'div\');\n  div.className = \'miniatura\';\n  div.textContent = \'✓ \' + nome;\n  document.getElementById(\'miniaturas\').appendChild(div);\n}\n\nfunction initPagamento() {\n  document.querySelectorAll(\'input[name="pagamento"]\').forEach(r => {\n    r.addEventListener(\'change\', () => {\n      document.getElementById(\'campo-plano\').style.display =\n        r.value === \'convenio\' ? \'block\' : \'none\';\n    });\n  });\n}\n\nfunction initCPF() {\n  const inp = document.getElementById(\'cpf\');\n  inp.addEventListener(\'input\', () => {\n    let v = inp.value.replace(/\\D/g,\'\').slice(0,11);\n    if (v.length > 9) v = v.replace(/(\\d{3})(\\d{3})(\\d{3})(\\d{1,2})/,\'$1.$2.$3-$4\');\n    else if (v.length > 6) v = v.replace(/(\\d{3})(\\d{3})(\\d{1,3})/,\'$1.$2.$3\');\n    else if (v.length > 3) v = v.replace(/(\\d{3})(\\d{1,3})/,\'$1.$2\');\n    inp.value = v;\n  });\n}\n\nfunction atualizarProgresso() {\n  for (let i = 1; i <= TOTAL_SECOES; i++) {\n    const d = document.getElementById(\'d\' + i);\n    if (i < secaoAtual)        d.className = \'dot feito\';\n    else if (i === secaoAtual) d.className = \'dot ativo\';\n    else                        d.className = \'dot\';\n  }\n  document.getElementById(\'prog-label\').textContent =\n    \'Se\xe7\xe3o \' + secaoAtual + \' de \' + TOTAL_SECOES + \'  \xb7  \' + TEMPO_EST[secaoAtual-1];\n  document.getElementById(\'prog-fill\').style.width =\n    ((secaoAtual - 1) / (TOTAL_SECOES - 1) * 100) + \'%\';\n\n  const btnProx = document.getElementById(\'btn-prox\');\n  const btnAnt  = document.getElementById(\'btn-ant\');\n  btnAnt.style.display = secaoAtual > 1 ? \'block\' : \'none\';\n  btnProx.textContent  = secaoAtual === TOTAL_SECOES ? \'✓ Enviar formul\xe1rio\' : \'Pr\xf3ximo →\';\n  btnProx.className    = secaoAtual === TOTAL_SECOES ? \'btn-enviar\' : \'btn-prox\';\n}\n\nfunction validarSecao(n) {\n  let ok = true;\n  if (n === 1) {\n    ok = validarCampo(\'c-regiao\', \'regiao_corpo\') & validarCampo(\'c-desc\', \'descricao\') && ok;\n  }\n  if (n === 2) {\n    ok = validarCampo(\'c-nasc\', \'nascimento\') &\n         validarCampo(\'c-cidade\', \'cidade\') &\n         validarCampo(\'c-profissao\', \'profissao\') && ok;\n  }\n  return ok;\n}\n\nfunction validarCampo(idCampo, idInput) {\n  const campo = document.getElementById(idCampo);\n  const inp   = document.getElementById(idInput);\n  if (!inp) return true;\n  const vazio = !inp.value || inp.value.trim() === \'\';\n  campo.classList.toggle(\'invalido\', vazio);\n  return !vazio;\n}\n\nfunction proximo() {\n  if (!validarSecao(secaoAtual)) return;\n  if (secaoAtual === TOTAL_SECOES) {\n    enviar();\n    return;\n  }\n  document.getElementById(\'sec\' + secaoAtual).classList.remove(\'ativa\');\n  secaoAtual++;\n  document.getElementById(\'sec\' + secaoAtual).classList.add(\'ativa\');\n  atualizarProgresso();\n  window.scrollTo(0, 0);\n}\n\nfunction anterior() {\n  document.getElementById(\'sec\' + secaoAtual).classList.remove(\'ativa\');\n  secaoAtual--;\n  document.getElementById(\'sec\' + secaoAtual).classList.add(\'ativa\');\n  atualizarProgresso();\n  window.scrollTo(0, 0);\n}\n\nasync function enviar() {\n  const btnProx = document.getElementById(\'btn-prox\');\n  btnProx.disabled = true;\n  btnProx.textContent = \'Enviando…\';\n\n  const mecanismo = document.querySelector(\'input[name="mecanismo"]:checked\');\n  const tabagismo = document.querySelector(\'input[name="tabagismo"]:checked\');\n  const alcool    = document.querySelector(\'input[name="alcool"]:checked\');\n  const pagamento = document.querySelector(\'input[name="pagamento"]:checked\');\n  const doencas   = Array.from(document.querySelectorAll(\'input[name="doencas"]:checked\')).map(i => i.value);\n\n  const payload = {\n    token: TOKEN,\n    exp: EXP,\n    agendamento_id: AID,\n    nome:           document.getElementById(\'nome\').value,\n    telefone:       document.getElementById(\'telefone\').value,\n    data_consulta:  DATA,\n    nascimento:     document.getElementById(\'nascimento\').value,\n    cpf:            document.getElementById(\'cpf\').value,\n    cidade:         document.getElementById(\'cidade\').value,\n    bairro:         document.getElementById(\'bairro\').value,\n    profissao:      document.getElementById(\'profissao\').value,\n    estado_civil:   document.getElementById(\'estado_civil\').value,\n    filhos:         parseInt(document.getElementById(\'filhos\').value) || 0,\n    doencas_cronicas: doencas,\n    medicacoes:         document.getElementById(\'medicacoes\').value,\n    alergias:           document.getElementById(\'alergias\').value,\n    cirurgias_anteriores: document.getElementById(\'cirurgias_anteriores\').value,\n    tabagismo:      tabagismo ? tabagismo.value : \'\',\n    alcool:         alcool    ? alcool.value    : \'\',\n    regiao_corpo:   document.getElementById(\'regiao_corpo\').value,\n    descricao:      document.getElementById(\'descricao\').value,\n    tempo_sintomas: document.getElementById(\'tempo_sintomas\').value,\n    mecanismo:      mecanismo ? mecanismo.value : \'\',\n    eva:            parseInt(document.getElementById(\'eva\').value),\n    piora:          document.getElementById(\'piora\').value,\n    melhora:        document.getElementById(\'melhora\').value,\n    tratamento_anterior: document.getElementById(\'tratamento_anterior\').value,\n    uso_analgesicos:     document.getElementById(\'uso_analgesicos\').value,\n    exames_urls:    examesUrls,\n    forma_pagamento: pagamento ? pagamento.value : \'particular\',\n    plano_saude:    document.getElementById(\'plano_saude\').value || null,\n  };\n\n  try {\n    const res = await fetch(\'/pre-consulta/submit\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify(payload),\n    });\n\n    if (!res.ok) {\n      const { erro, token_expirado } = await res.json();\n      if (token_expirado) { mostrarExpirado(); return; }\n      alert(\'Erro ao enviar: \' + erro);\n      btnProx.disabled = false;\n      btnProx.textContent = \'✓ Enviar formul\xe1rio\';\n      return;\n    }\n\n    const dataFmt = DATA ? new Date(DATA).toLocaleDateString(\'pt-BR\') : \'\';\n    const horaFmt = DATA ? new Date(DATA).toLocaleTimeString(\'pt-BR\',{hour:\'2-digit\',minute:\'2-digit\'}) : \'\';\n    location.href = \'/confirmacao?nome=\' + encodeURIComponent(NOME) + \'&data=\' + encodeURIComponent(dataFmt) + \'&hora=\' + encodeURIComponent(horaFmt);\n  } catch {\n    alert(\'Falha de rede. Verifique sua conex\xe3o e tente novamente.\');\n    btnProx.disabled = false;\n    btnProx.textContent = \'✓ Enviar formul\xe1rio\';\n  }\n}\n\ninit();\n</script>\n</body>\n</html>'},style:{all:"unset"}})}},30622:function(n,e,a){"use strict";var o=a(2265),t=Symbol.for("react.element"),i=Symbol.for("react.fragment"),l=Object.prototype.hasOwnProperty,r=o.__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED.ReactCurrentOwner,s={key:!0,ref:!0,__self:!0,__source:!0};function d(n,e,a){var o,i={},d=null,c=null;for(o in void 0!==a&&(d=""+a),void 0!==e.key&&(d=""+e.key),void 0!==e.ref&&(c=e.ref),e)l.call(e,o)&&!s.hasOwnProperty(o)&&(i[o]=e[o]);if(n&&n.defaultProps)for(o in e=n.defaultProps)void 0===i[o]&&(i[o]=e[o]);return{$$typeof:t,type:n,key:d,ref:c,props:i,_owner:r.current}}e.Fragment=i,e.jsx=d,e.jsxs=d},57437:function(n,e,a){"use strict";n.exports=a(30622)}},function(n){n.O(0,[2971,4938,1744],function(){return n(n.s=56271)}),_N_E=n.O()}]);